package com.exito.chop;
final class AudioRender {
 static short[] chop(short[] data,int sr,int from,int to,PadParams p,float comp,float verb,Mutator.Settings fx,Heat.Settings heat,boolean wet){from=Math.max(0,from);to=Math.max(from+1,Math.min(data.length/2,to));int tail=wet&&(verb>0||fx.diffusion>0)?(int)(sr*2.5):0,frames=to-from+tail;short[] out=new short[frames*2];float[] block=new float[1024];Vintage vintage=new Vintage(sr);Dsp.Fx processor=new Dsp.Fx(sr);Mutator mutation=new Mutator(sr);Heat warmth=new Heat(sr);for(int at=0;at<frames;at+=512){int n=Math.min(512,frames-at);for(int i=0;i<n;i++){int pos=from+at+i;double fade=pos<to?Math.max(0,Math.min(1,Math.min((pos-from+1)/(sr*.003),(to-pos)/(sr*.003)))):0;for(int c=0;c<2;c++)block[i*2+c]=pos<to?(float)(data[pos*2+c]/32768.*fade):0;}if(wet){vintage.process(block,n*2,p);processor.process(block,n*2,comp,verb);mutation.process(block,n*2,fx);warmth.process(block,n*2,heat,(int)fx.bpm);}for(int i=0;i<n*2;i++)out[at*2+i]=Mutator.quantize(block[i]);}return out;}
}
